#pragma once
#include <stdint.h>
#include "SpriteInk.h"
#include "../services/PetModel.h"

namespace deskos {
// VOLT, the DeskOS robot mascot: 48x48 front-facing chibi drawn at 2x in the
// existing 96x96 area. Pose frames, LED-eye and crown overlays are flash
// constants generated by tools/pet_art/generate_pet.py and composed into a
// caller-owned canvas: no heap, no framebuffer. The upside-down Hang frames
// are the Cheer frame flipped vertically. Presentation enums are never stored in NVS.
constexpr uint8_t PET_SPRITE_SIZE=48;
enum class PetPose : uint8_t { Relaxed, Breathe, Wave, WaveFlick, Sleep, SleepBreathe, Cheer, CheerBounce,
                               Laugh, LaughShake, GrappleLeft, GrappleRight, Hang, HangSwing, Count };
enum class PetEyes : uint8_t { Open, Closed, Happy, Sleepy, Star, Heart, Count };
struct PetFrame { PetPose pose; PetEyes eyes; bool crown; };
struct PetCanvas { char rows[PET_SPRITE_SIZE][PET_SPRITE_SIZE+1]; };
constexpr uint8_t PET_HANG_SWING=2;  // HangSwing shifts the hanging hero right by this many cells.
void composePet(PetCanvas& out,const PetFrame& frame);
// First canvas row of the head (antenna included) for an upright pose.
uint8_t petHeadTop(PetPose pose);
// Last row of the head when standing: taps above it are head pats, below it tickles.
uint8_t petHeadBottom();
// Row of the grapple cable leaving the hand in GrappleLeft/GrappleRight.
uint8_t petCableRow();
// Colours of the sprite characters ('.' is the screen background).
const SpriteInk* petInks();
uint8_t petInkCount();
// Frame selection is pure so it can be tested without a display.
PetFrame petFrame(PetMood mood,PetStyle style,uint32_t moodElapsedMs,uint32_t animMs);
PetFrame petFrame(PetMood mood,PetReaction reaction,PetStyle style,uint32_t moodElapsedMs,
                  uint32_t reactionElapsedMs,uint32_t animMs);
uint8_t petFrameKey(const PetFrame& frame);
// Checks dimensions and palette characters in every stored layer.
bool petSpritesWellFormed();
}  // namespace deskos
